data.script:
function check(v,label){if(!v)throw Error(label);}
const before=editor.getText(), selection=editor.getSelectedRange().join(',');
const night=Theme.find('custom','QA Theme night café 🐼'),day=Theme.find('custom','QA Theme day');
check(night instanceof Theme&&day instanceof Theme,'theme catalog');
app.darkTheme=night;app.lightTheme=day;app.themeMode='dark';
check(app.darkTheme instanceof Theme&&app.darkTheme.name===night.name,'configured dark');
check(app.lightTheme instanceof Theme&&app.lightTheme.name===day.name,'configured light');
check(editor.getText()===before&&editor.getSelectedRange().join(',')===selection,'editor preserved');
app.displaySuccessMessage('Configured theme pair passed');
